// Example using AWS SDK v2 to send a message to SQS
SqsClient sqsClient = SqsClient.builder().region(Region.US_EAST_1).build();

SendMessageRequest request = SendMessageRequest.builder()
    .queueUrl("https://sqs.us-east-1.amazonaws.com/12345/my-queue")
    .messageBody("{\"orderId\": \"ORD-99\", \"status\": \"CREATED\"}")
    .build();


sqsClient.sendMessage(request);
